#define CHECK(arg) if(!(arg)){fprintf(stderr, "failed CHECK at line %d: %s\n", __LINE__, #arg); abort();}

static s64 pickhardt_richter_probability_ppm(
		struct amount_msat low,
		struct amount_msat high,
		struct amount_msat x){
	s64 ret =  1e6 * pickhardt_richter_probability(low, high, x);
	assert(ret >= 0);
	assert(ret <= 1000000);
	return ret;
}

static void test_richter_pickhardt_linearity(void)
{
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(0)) == 1000000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(1)) == 990000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(2)) == 980000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(3)) == 970000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(4)) == 960000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(5)) == 950000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(10)) == 900000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(20)) == 800000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(30)) == 700000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(40)) == 600000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(50)) == 500000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(60)) == 400000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(70)) == 300000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(80)) == 200000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(90)) == 100000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(95)) == 50000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(99)) == 10000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(100)) == 0);

	for (u64 i = 0; i <= 1000; i++) {
		CHECK(pickhardt_richter_probability_ppm(
			  AMOUNT_MSAT(0), AMOUNT_MSAT(1000), amount_msat(i)) ==
		      (1000 - i) * 1000);
		CHECK(pickhardt_richter_probability_ppm(
			  AMOUNT_MSAT(123), AMOUNT_MSAT(1123),
			  amount_msat(i + 123)) == (1000 - i) * 1000);
		CHECK(pickhardt_richter_probability_ppm(
			  AMOUNT_MSAT(1123), AMOUNT_MSAT(2123),
			  amount_msat(i + 1123)) == (1000 - i) * 1000);
	}
}

static void test_richter_pickhardt_low_ranges(void){
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(0)) == 1000000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(1), AMOUNT_MSAT(100), AMOUNT_MSAT(0)) == 1000000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(1), AMOUNT_MSAT(100), AMOUNT_MSAT(1)) == 1000000);

	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(10), AMOUNT_MSAT(100), AMOUNT_MSAT(10)) == 1000000);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(10), AMOUNT_MSAT(100), AMOUNT_MSAT(9)) == 1000000);

	for (u64 low = 0; low <= 1000; low++)
		for (u64 x = 0; x <= low; x++) {
			CHECK(pickhardt_richter_probability_ppm(
				  amount_msat(low), AMOUNT_MSAT(1001),
				  amount_msat(x)) == 1000000);
		}
}

static void test_richter_pickhardt_high_ranges(void){
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(100)) == 0);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(101)) == 0);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(102)) == 0);
	CHECK(pickhardt_richter_probability_ppm(
		  AMOUNT_MSAT(0), AMOUNT_MSAT(100), AMOUNT_MSAT(200)) == 0);

	for (u64 x = 0; x <= 1000; x++) {
		CHECK(pickhardt_richter_probability_ppm(
			  AMOUNT_MSAT(0), AMOUNT_MSAT(1000),
			  amount_msat(x + 1000)) == 0);

		CHECK(pickhardt_richter_probability_ppm(
			  AMOUNT_MSAT(999), AMOUNT_MSAT(1000),
			  amount_msat(x + 1000)) == 0);

		CHECK(pickhardt_richter_probability_ppm(
			  AMOUNT_MSAT(0), AMOUNT_MSAT(2000),
			  amount_msat(x + 2000)) == 0);
	}
}

int main(int argc, char *argv[])
{
	common_setup(argv[0]);

	test_richter_pickhardt_linearity();
	test_richter_pickhardt_low_ranges();
	test_richter_pickhardt_high_ranges();

	common_shutdown();
	return 0;
}
